import React from 'react';
import {
  Input as ArcoInput,
  InputProps as ArcoInputProps,
  TextAreaProps as ArcoTextAreaProps
} from '@arco-design/web-react';
import {
  InputPasswordProps as ArcoInputPasswordProps,
  InputSearchProps as ArcoInputSearchProps
} from '@arco-design/web-react/es/Input';
import { InputGroupProps as ArcoInputGroupProps } from '@arco-design/web-react/es/Input/interface';
import { IconLoading } from '@arco-design/web-react/icon';
import { connect, mapProps, mapReadPretty } from '@formily/react';
import { Field } from '@formily/core';

import { PreviewText } from '../PreviewText';

type ComposedInput = React.FC<ArcoInputProps> & {
  TextArea?: React.FC<ArcoTextAreaProps>;
  Group?: React.FC<ArcoInputGroupProps>;
  Password?: React.FC<ArcoInputPasswordProps>;
  Search?: React.FC<ArcoInputSearchProps>;
};

const Input: ComposedInput = connect(
  ArcoInput,
  mapProps((props, field: Field) => ({
    ...props,
    suffix: <span>{field?.loading || field?.validating ? <IconLoading /> : props.suffix}</span>,
  })),
  mapReadPretty(PreviewText.Input)
);

Input.Group = connect(ArcoInput.Group);

Input.TextArea = connect(ArcoInput.TextArea, mapReadPretty(PreviewText.Input));

Input.Password = connect(ArcoInput.Password);

Input.Search = connect(ArcoInput.Search, mapReadPretty(PreviewText.Input));

export default Input;
